// Aptitude & reasoning: methods/shortcuts in Tamil + question generators with exact answers.
// Generated by code (not AI), so every answer is mathematically correct.

export type AptQ = { stem: string; options: string[]; answer_index: number; explanation: string };
export type AptType = {
  key: string;
  name: string;
  unit: "aptitude" | "reasoning";
  method: string[]; // steps / formulas (Tamil)
  shortcuts: string[];
  gen: () => AptQ;
};

const ri = (a: number, b: number) => a + Math.floor(Math.random() * (b - a + 1));
const pick = <T,>(a: T[]) => a[Math.floor(Math.random() * a.length)];
const gcd = (a: number, b: number): number => (b ? gcd(b, a % b) : a);
const lcm = (a: number, b: number) => (a / gcd(a, b)) * b;
const fmt = (n: number) => (Number.isInteger(n) ? String(n) : n.toFixed(2).replace(/\.?0+$/, ""));

/** Build 4 distinct options around the answer and return them shuffled. */
function opts(answer: number, spread: number[] = [], suffix = ""): { options: string[]; answer_index: number } {
  const set = new Set<number>([answer]);
  const cands = [...spread, answer + 1, answer - 1, answer * 2, Math.round(answer * 1.1), Math.round(answer * 0.9), answer + 10, answer - 10, answer + 5];
  for (const c of cands) {
    if (set.size >= 4) break;
    if (c > 0 && c !== answer) set.add(c);
  }
  let k = 2;
  while (set.size < 4) set.add(answer + k++);
  const arr = [...set].sort(() => Math.random() - 0.5);
  return { options: arr.map((x) => fmt(x) + suffix), answer_index: arr.indexOf(answer) };
}

