export const aptType = (key: string) => APT_TYPES.find((t) => t.key === key);
export function drill(keys: string[], n: number): (AptQ & { type: string })[] {
  const types = APT_TYPES.filter((t) => keys.includes(t.key));
  const list = types.length ? types : APT_TYPES;
  return Array.from({ length: n }, (_, i) => {
    const t = list[i % list.length];
    return { ...t.gen(), type: t.key };
  });
}
